# Fix the transform - actually checking all 4 neighbors for secondary color
def transform_fixed(grid):
    if not grid or not grid[0]:
        return grid
    rows, cols = len(grid), len(grid[0])
    colors = [c for row in grid for c in row]
    from collections import Counter
    bg = Counter(colors).most_common(1)[0][0]
    secondary = sorted([c for c in set(colors) if c != bg], reverse=True)[0]
    new_color = 3

    result = [row[:] for row in grid]
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == bg:
                # Check all 4 neighbors
                has_secondary = False
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == secondary:
                        has_secondary = True
                        break
                if has_secondary:
                    result[r][c] = new_color
    return result

