def get_value(grid, r, c, offset_r, offset_c):
    """Get a value from grid, checking bounds"""
    rows, cols = len(grid), len(grid[0])
    if 0 <= r + offset_r < rows and 0 <= c + offset_c < cols:
        return grid[r + offset_r][c + offset_c]
    return None

