ROWS, COLS = 10, 4

from collections import deque

def same_component(grid, neighbors1, neighbors2):
    # BFS from neighbor1 to see if we can reach neighbor2 through same-valued cells
    start = neighbors1
    visited = set()
    queue = deque([start])
    while queue:
        curr = queue.popleft()
        if curr == neighbors2:
            return True
        if curr in visited:
            continue
        visited.add(curr)
        r, c = neighbors1[0], neighbors1[1]
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < ROWS and 0 <= nc < COLS and grid[nr][nc] == grid[r][c] and (nr, nc) not in visited:
                queue.append((nr, nc))
    return False

