# Find all 6s in each row and column
def is_alone_6(grid, r, c):
    """Check if 6 at (r,c) has no 6 neighbors in 4 directions"""
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < ROWS and 0 <= nc < COLS and grid[nr][nc] == 6:
            return False
    return True

alone_6s = set()
for r in range(ROWS):
    for c in range(COLS):
        if demo_in[r][c] == 6 and is_alone_6(demo_in, r, c):
            alone_6s.add((r, c))
